import json

# Look at the full structure of one file
with open('/app/resources/treasury_bulletin_1972_03.json', 'r') as f:
    data = json.load(f)

doc = data['document']

# Look for elements
if 'elements' in doc:
    print("Elements:")
    for i, elem in enumerate(doc['elements']):
        if 'table' in elem or 'text' in elem:
            print(f"\nElement {i}: {list(elem.keys())}")
            if 'table' in elem:
                table = elem['table']
                if 'title' in table:
                    print(f"  Title: {table['title']}")
                if 'data' in table and table['data']:
                    print(f"  Data rows: {len(table['data'])}")
                    # Look for rows with year and Total
                    for j, row in enumerate(table['data'][:20]):
                        row_str = str(row)
                        if 'Total' in row_str:
                            print(f"    Row {j}: {row}")
